 let content,type='text/html; charset=utf-8',responseStatus=200;
 const plainAsset=plainIdentityAsset(path);
 if(path==='/robots.txt')return new Response(request.method==='HEAD'?null:createRobotsTxt(url.origin),{headers:{'content-type':'text/plain; charset=utf-8','cache-control':'public, max-age=300'}});
 if(path==='/sitemap.xml')return new Response(request.method==='HEAD'?null:createSitemapXml(url.origin),{headers:{'content-type':'application/xml; charset=utf-8','cache-control':'public, max-age=300'}});
 if(plainAsset){content=plainAsset;type='image/svg+xml';}
 else if(path.startsWith('/assets/fonts/')&&fontAssets[path.slice(14).replace(/\.woff2$/,'')]){content=Uint8Array.from(atob(fontAssets[path.slice(14).replace(/\.woff2$/,'')]),c=>c.charCodeAt(0));type='font/woff2';}
 else if(path==='/api/race-calendar'){content=JSON.stringify({events:calendarEvents.map(e=>({...e,sessions:sessionSchedule[e.id]||[],seriesIds:[e.series,...(e.seriesAliases||[])]})),circuits:circuitInfo,trackMaps,checkedAt:calendarReviewedAt,supported:championships.filter(c=>c.group!=='reference').map(c=>c.slug)});type='application/json; charset=utf-8';}
 else if(path==='/assets/race-features.js'){content=scriptAsset('race-features');type='text/javascript; charset=utf-8';}
 else if(['/assets/imsa-official','/assets/imsa-official.svg','/assets/nls-official','/assets/nls-official.svg'].includes(path)){content=seriesVectorAssets[path.includes('/imsa-')?'imsa':'nls'];type='image/svg+xml';}
 else if(path==='/assets/brand-mark-en.svg'){content=ciLogos['en-dark'];type='image/svg+xml';}
 else if(path==='/assets/team-logos.js'){content='export const teamLogoFor='+teamLogoFor.toString()+';';type='text/javascript; charset=utf-8';}
 else if(path.startsWith('/assets/ci/')&&ciLogos[path.slice(11).replace(/\.svg$/,'')]&&path.endsWith('.svg')){content=ciLogos[path.slice(11,-4)];type='image/svg+xml';}
 else if(path==='/assets/brand-icon.svg'){content=ciTabIcon;type='image/svg+xml';}
 else if(path==='/assets/brand-icon.png'){content=Uint8Array.from(atob(brandIconBase64),c=>c.charCodeAt(0));type='image/png';}
 else if(path==='/assets/brand-mark.svg'){content=ciLogos['ko-dark'];type='image/svg+xml';}
 else if(path==='/assets/brand-mark-light.svg'){content=ciLogos['ko-light'];type='image/svg+xml';}
 else if(path==='/assets/brand-mark-light-en.svg'){content=ciLogos['en-light'];type='image/svg+xml';}
