 document.querySelectorAll('[data-copy-target]').forEach(b=>b.addEventListener('click',async()=>{const el=document.getElementById(b.dataset.copyTarget);try{await navigator.clipboard.writeText(el.textContent);const label=b.textContent;b.textContent=document.documentElement.lang==='en'?'Copied':'복사했습니다';setTimeout(()=>{b.textContent=label;},1600);}catch{b.textContent=document.documentElement.lang==='en'?'Copy failed':'복사 실패';}}));
