 document.addEventListener('keydown',event=>{if(event.key==='Escape'&&mobileMenu.matches&&menu?.getAttribute('aria-expanded')==='true'){menu.click();menu.focus({preventScroll:true});}});
 document.querySelectorAll('[data-copy],[data-copy-from]').forEach(b=>b.addEventListener('click',async()=>{const text=b.dataset.copyFrom?document.getElementById(b.dataset.copyFrom)?.textContent||'':b.dataset.copy;try{await navigator.clipboard.writeText(text);feedback('복사했습니다. 사용하는 AI의 연결 설정이나 대화에 붙여넣으세요.');}catch{feedback('자동 복사를 사용할 수 없습니다. 아래 텍스트를 선택해 복사하세요.');const t=document.createElement('textarea');t.value=text;t.readOnly=true;($('#feedback')||$('#copy-feedback')).after(t);t.focus();t.select();}}));
